"use client";

import { loadFont } from "@remotion/google-fonts/AzeretMono";
import type React from "react";
import { AbsoluteFill, Easing, interpolate } from "remotion";
import { useSceneConfig, useSceneFrame } from "@/lib/remocn/frame-rate";
import { useGlide } from "@/lib/remocn/glide";
import { type Timing, useTimeline } from "@/lib/remocn/timeline";
import {
  clockStart,
  PREROLL,
  type ShotClockElementId,
  shotClockTimeline,
} from "./timeline";

const { fontFamily: mono } = loadFont("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

export interface ShotClockProps {
  /** Seconds on the clock when it starts. Whole seconds, then tenths below `tenthsBelow`. */
  from?: number;
  /** Below this many seconds the clock shows tenths and turns red. */
  tenthsBelow?: number;
  /** The big word that slams in at the buzzer. Set in caps. */
  title?: string;
  /** The line under it. */
  subtitle?: string;
  /** Small label over the clock, left. */
  label?: string;
  /** Small label over the clock, right. */
  period?: string;
  /** Colour of the last seconds and the buzzer light. */
  alarm?: string;
  /** The live marker next to the period label. */
  accent?: string;
  /** Color of the running clock, subtitle and possession bar; overrides the theme ink. */
  ink?: string;
  /** Background fill; "transparent" drops it. */
  background?: string;
  /** Typeface for the clock and copy. Load it yourself; Azeret Mono by default. */
  fontFamily?: string;
  /** Frames per whole-second tick. */
  tick?: number;
  /** Frames the 0.0 holds at the buzzer before the clock shrinks away. */
  hold?: number;
  /** Size of the clock and title, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  theme?: "dark" | "light";
  speed?: number;
  /**
   * Moves, trims or stretches the drop, the seconds, the tenths, the buzzer,
   * the shrink, the title and the subtitle, by the ids in `./timeline`.
   * Frames on the scene timeline, after `delay` and `speed`.
   */
  timing?: Timing<ShotClockElementId>;
}

// Beat sheet (internal clock = frame + 2, 30fps, speed 1, from 24):
//   0–9    "24" drops in; the light bar over it and the possession bar under
//          it draw out from the centre, labels fade up
//  14–64   the whole seconds tick down, one every 2.6 frames, while the clock
//          pushes in slowly (7% by the buzzer)
//  64      "5.0": the clock turns red with a kick and starts counting tenths,
//          one per frame; the possession bar runs out with it
// 114      0.0, the buzzer: the frame flashes with the "rise" gradient, the
//          light bar goes solid red and stays lit; the 0.0 holds 6 frames
// 120–131  the clock shrinks up under the light; the title slams in at the
//          centre as it clears, the subtitle four frames after it
// 135–     poster hold

const SLAM = Easing.bezier(0.22, 1, 0.36, 1);
const MOVE = Easing.bezier(0.7, 0, 0.2, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

// gradients.sh "rise": bg #030306, #fff1e2 #ff8a3d #a3301a #2a0d0a.
const RISE = ["#FFF1E2", "#FF8A3D", "#A3301A", "#2A0D0A"] as const;

const THEMES = {
  dark: {
    stage: "#0A0A0B",
    ink: "#F3F2EF",
    dim: "#86858C",
    track: "#1C1C20",
    flashOp: 1,
    titleFill: `linear-gradient(180deg, ${RISE[0]} 8%, ${RISE[1]} 55%, #E0502A 100%)`,
  },
  light: {
    stage: "#F5F4F0",
    ink: "#121214",
    dim: "#7E7D77",
    track: "#E2E0D9",
    flashOp: 0.9,
    titleFill: `linear-gradient(180deg, ${RISE[1]} 0%, #E0502A 50%, ${RISE[2]} 100%)`,
  },
} as const;

/** Whether any of the pixel values `at` returns moves around `t`. */
function moves(at: (t: number) => number[], t: number, step: number) {
  const [a, b, c] = [at(t - step), at(t), at(t + step)];
  return b.some(
    (v, i) => Math.abs(c[i] - v) > 1e-3 || Math.abs(v - a[i]) > 1e-3,
  );
}

function ramp(t: number, from: number, len: number) {
  return interpolate(t, [from, from + len], [0, 1], CLAMP);
}

/** A short hit: up in 1 frame, eases back over `len`. */
function kick(d: number, len: number) {
  if (d < 0 || d > len + 1) return 0;
  if (d < 1) return d;
  const k = 1 - (d - 1) / len;
  return k * k;
}

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

export function ShotClock(props: ShotClockProps) {
  const {
    from = 24,
    tenthsBelow = 5,
    title = "Shipped",
    subtitle = "at the buzzer",
    label = "Shot clock",
    period = "Q4 · 00:24",
    alarm = "#FF4433",
    accent = "#3B5BFD",
    ink,
    background,
    fontFamily = mono,
    scale = 1,
    delay = 0,
    theme = "dark",
    speed = 1,
    timing,
  } = props;
  const glide = useGlide();
  // Starts two frames in, so frame 0 already shows the drop.
  const t = Math.max(0, useSceneFrame() - delay) * speed + PREROLL;
  const { width: W, height: H, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    shotClockTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  // The schedule counts scene frames; `t` runs `PREROLL` ahead of them.
  const dropEl = tl.get("drop");
  const secondsEl = tl.get("seconds");
  const tenthsEl = tl.get("tenths");
  const buzzerEl = tl.get("buzzer");
  const shrinkEl = tl.get("shrink");
  const titleEl = tl.get("title");
  const subtitleEl = tl.get("subtitle");
  const dropStart = dropEl.start + PREROLL;
  const tickAt = secondsEl.start + PREROLL;
  const tick = secondsEl.beat("tick");
  const tenth = tenthsEl.beat("tenth");
  const c = THEMES[theme];
  const fg = ink ?? c.ink;
  const stage =
    background === "transparent" ? "transparent" : (background ?? c.stage);
  const u = Math.min(W / 1280, H / 720);

  const start = clockStart(from, tenthsBelow);
  const redAt = tenthsEl.start + PREROLL;
  const buzzAt = buzzerEl.start + PREROLL;

  // Clock value in tenths of a second.
  let tenths: number;
  if (t < tickAt) tenths = start * 10;
  else if (t < redAt) tenths = (start - Math.floor((t - tickAt) / tick)) * 10;
  else tenths = Math.max(0, tenthsBelow * 10 - Math.floor((t - redAt) / tenth));
  const red = t >= redAt;
  const buzzed = t >= buzzAt;
  const text = red
    ? `${Math.floor(tenths / 10)}.${tenths % 10}`
    : `${Math.round(tenths / 10)}`;

  // Possession bar: continuous, so it runs smoothly between ticks.
  const remaining = interpolate(
    t,
    [tickAt, redAt, buzzAt],
    [start, tenthsBelow, 0],
    CLAMP,
  );
  const barFrac = remaining / start;

  // ── Layout ────────────────────────────────────────────────────────────────
  const clockFs = 380 * u;
  const blockW = 820 * u;
  const cx = W / 2;
  const clockCY = H / 2 + 14 * u;
  const lightY = clockCY - 0.5 * clockFs - 34 * u;
  const barY = clockCY + 0.5 * clockFs + 18 * u;

  const dropAt = (tt: number) => SLAM(ramp(tt, dropStart, dropEl.length));
  const drop = dropAt(t);
  const draw = SLAM(
    ramp(t, dropStart + dropEl.beat("draw"), dropEl.beat("drawLen")),
  );
  const labelsIn = ramp(
    t,
    dropStart + dropEl.beat("labels"),
    dropEl.beat("labelsLen"),
  );
  const flash = buzzed ? kick(t - buzzAt, buzzerEl.beat("flash")) : 0;

  // Shrink to the poster position under the light.
  const posterScale = 0.38;
  const posterCY = 150 * u;
  const groupAt = (tt: number) => {
    const shrink = MOVE(ramp(tt, shrinkEl.start + PREROLL, shrinkEl.length));
    // A slow push-in while the clock runs down builds the pressure.
    const push = Easing.bezier(
      0.65,
      0,
      0.35,
      1,
    )(ramp(tt, tickAt, buzzAt - tickAt));
    const scale =
      interpolate(shrink, [0, 1], [1 + 0.07 * push, posterScale]) *
      (1 +
        0.03 * kick(tt - redAt, tenthsEl.beat("kick")) +
        0.04 * kick(tt - buzzAt, buzzerEl.beat("kick")));
    const dy = interpolate(shrink, [0, 1], [0, posterCY - clockCY]);
    return { shrink, scale, dy };
  };
  const { shrink, scale: groupScale, dy: groupDY } = groupAt(t);
  const sideFade = 1 - ramp(shrink, 0, 0.4);
  const groupMoving = moves(
    (tt) => {
      const g = groupAt(tt);
      return [g.dy, g.scale * W, (1 - dropAt(tt)) * 90 * u];
    },
    t,
    speed,
  );

  const titleAt = titleEl.start + PREROLL;
  const titleScaleAt = (tt: number) =>
    (1.22 - 0.22 * SLAM(ramp(tt, titleAt, titleEl.length))) *
    (1 +
      0.025 *
        kick(tt - (titleAt + titleEl.beat("kickAt")), titleEl.beat("kick")));
  const subAt = (tt: number) =>
    SLAM(ramp(tt, subtitleEl.start + PREROLL, subtitleEl.length));
  const titleIn = SLAM(ramp(t, titleAt, titleEl.length));
  const subIn = subAt(t);
  const titleMoving = moves((tt) => [titleScaleAt(tt) * W], t, speed);
  const subMoving = moves((tt) => [(1 - subAt(tt)) * 36 * u], t, speed);

  const clockColor = red ? alarm : fg;
  const lightOn = buzzed;

  const chars = text.split("");

  const smallLabel: React.CSSProperties = {
    fontFamily,
    fontWeight: 400,
    fontSize: 17 * u,
    letterSpacing: "0.16em",
    textTransform: "uppercase",
    color: c.dim,
  };

  // Rise ground, lingering after the buzzer.
  const ground = [
    `radial-gradient(70% 55% at 50% 108%, color-mix(in oklab, ${RISE[1]} 55%, transparent) 0%, transparent 70%)`,
    `radial-gradient(45% 35% at 50% 100%, color-mix(in oklab, ${RISE[0]} 35%, transparent) 0%, transparent 70%)`,
    `radial-gradient(90% 70% at 50% 115%, color-mix(in oklab, ${RISE[2]} 70%, transparent) 0%, transparent 80%)`,
  ].join(", ");
  const groundOp =
    (theme === "dark" ? 0.75 : 0.45) * ramp(t, buzzAt, buzzerEl.beat("ground"));

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      <div
        style={{
          position: "absolute",
          inset: 0,
          background: ground,
          opacity: groundOp,
        }}
      />

      <ScaleLayer scale={scale}>
        {/* Clock group: light, labels, digits, possession bar. */}
        <div
          style={{
            position: "absolute",
            inset: 0,
            transform: `translateY(${groupDY}px) scale(${groupScale})${glide(groupMoving)}`,
            transformOrigin: `${cx}px ${clockCY}px`,
          }}
        >
          {/* Buzzer light. */}
          <div
            style={{
              position: "absolute",
              left: cx - (blockW / 2) * draw,
              top: lightY,
              width: blockW * draw,
              height: 14 * u,
              background: lightOn ? alarm : c.track,
            }}
          />
          <div
            style={{
              ...smallLabel,
              position: "absolute",
              left: cx - blockW / 2,
              top: lightY - 40 * u,
              opacity: labelsIn * sideFade,
            }}
          >
            {label}
          </div>
          <div
            style={{
              ...smallLabel,
              position: "absolute",
              right: W - (cx + blockW / 2),
              top: lightY - 40 * u,
              opacity: labelsIn * sideFade,
              display: "flex",
              alignItems: "center",
              gap: 10 * u,
            }}
          >
            <div
              style={{
                width: 8 * u,
                height: 8 * u,
                background: accent,
                opacity: buzzed ? 0 : Math.floor(t / 15) % 2 === 0 ? 1 : 0.35,
              }}
            />
            {period}
          </div>

          {/* Digits. */}
          <div
            style={{
              position: "absolute",
              left: 0,
              right: 0,
              top: clockCY - clockFs / 2,
              height: clockFs,
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              fontFamily,
              fontWeight: 500,
              fontSize: clockFs,
              lineHeight: 1,
              letterSpacing: "-0.04em",
              color: clockColor,
              transform: `translateY(${-(1 - drop) * 90 * u}px)`,
              opacity: drop,
            }}
          >
            {chars.map((ch, i) =>
              ch === "." ? (
                <span
                  key={i}
                  style={{
                    width: "0.42em",
                    display: "inline-flex",
                    justifyContent: "center",
                  }}
                >
                  .
                </span>
              ) : (
                <span key={i} style={{ display: "inline-block" }}>
                  {ch}
                </span>
              ),
            )}
          </div>

          {/* Possession bar, running out towards the centre. */}
          <div
            style={{
              position: "absolute",
              left: cx - (blockW / 2) * draw,
              top: barY,
              width: blockW * draw,
              height: 6 * u,
              background: c.track,
              opacity: sideFade,
            }}
          />
          <div
            style={{
              position: "absolute",
              left: cx - (blockW / 2) * draw * barFrac,
              top: barY,
              width: blockW * draw * barFrac,
              height: 6 * u,
              background: red ? alarm : fg,
              opacity: sideFade,
            }}
          />
        </div>

        {/* Title. */}
        <div
          style={{
            position: "absolute",
            left: 0,
            right: 0,
            top: H / 2 - 120 * u,
            display: "flex",
            justifyContent: "center",
            opacity: ramp(titleIn, 0, 0.25),
            transform: `scale(${titleScaleAt(t)})${glide(titleMoving)}`,
            transformOrigin: `${cx}px ${100 * u}px`,
          }}
        >
          <div
            style={{
              fontFamily,
              fontWeight: 500,
              fontSize: 176 * u,
              lineHeight: 1.15,
              letterSpacing: "-0.05em",
              textTransform: "uppercase",
              whiteSpace: "nowrap",
              backgroundImage: c.titleFill,
              WebkitBackgroundClip: "text",
              backgroundClip: "text",
              color: "transparent",
            }}
          >
            {title}
          </div>
        </div>
        <div
          style={{
            position: "absolute",
            left: 0,
            right: 0,
            top: H / 2 + 112 * u,
            display: "flex",
            justifyContent: "center",
            fontFamily,
            fontWeight: 400,
            fontSize: 46 * u,
            letterSpacing: "0.04em",
            textTransform: "uppercase",
            color: fg,
            whiteSpace: "nowrap",
            opacity: subIn,
            transform: `translateY(${(1 - subIn) * 36 * u}px)${glide(subMoving)}`,
          }}
        >
          {subtitle}
        </div>
      </ScaleLayer>

      {/* Buzzer flash. */}
      {flash > 0 ? (
        <div
          style={{
            position: "absolute",
            inset: 0,
            background: `radial-gradient(120% 90% at 50% 100%, ${RISE[0]} 0%, ${RISE[1]} 38%, ${RISE[2]} 72%, ${RISE[3]} 100%)`,
            opacity: flash * c.flashOp,
          }}
        />
      ) : null}
    </AbsoluteFill>
  );
}

import { defineTimeline, type TimelineElement } from "@/lib/remocn/timeline";

// The clock dropping in, the whole seconds ticking down, the red tenths, the
// buzzer, the clock shrinking away and the title and subtitle slamming in.
// Frames on the 30 fps scene timeline, after `delay` and `speed`. The ids
// are public: a saved `timing` prop refers to them.

export type ShotClockElementId =
  | "drop"
  | "seconds"
  | "tenths"
  | "buzzer"
  | "shrink"
  | "title"
  | "subtitle";

export interface ShotClockTimingProps {
  from?: number;
  tenthsBelow?: number;
  tick?: number;
  hold?: number;
}

/** The scene starts this far into its choreography: frame 0 already moves. */
export const PREROLL = 2;
const DROP_AT = 0;
const TICK_AT = 14;
const TICK = 2.6;
const TENTH = 1;
const SHRINK_DELAY = 6;
const SHRINK_LEN = 11;

/** The whole seconds the clock starts from. */
export function clockStart(from: number, tenthsBelow: number) {
  return Math.max(tenthsBelow + 1, Math.floor(from));
}

// `drop` brings the clock in; the light and the bar draw from `draw` over
// `drawLen`, the labels fade up from `labels` over `labelsLen`. `seconds`
// ticks a whole second every `tick`; `tenths` turns the clock red with a
// `kick` and counts a tenth every `tenth`; `buzzer` is the 0.0, flashing
// the frame (`flash`), kicking the clock and lifting the glow (`ground`),
// held for its length. Then `shrink`, `title` (with a `kick` at `kickAt`)
// and `subtitle`. Each follows the one before.
export const shotClockTimeline = defineTimeline<
  ShotClockElementId,
  ShotClockTimingProps
>(
  ({
    from = 24,
    tenthsBelow = 5,
    tick = TICK,
    hold = SHRINK_DELAY,
  }): TimelineElement<ShotClockElementId>[] => {
    const start = clockStart(from, tenthsBelow);
    const wholeTicks = start - tenthsBelow;
    const redAt = TICK_AT + wholeTicks * tick;
    const buzzAt = redAt + tenthsBelow * 10 * TENTH;
    const shrinkAt = buzzAt + hold;
    const titleAt = buzzAt + hold + SHRINK_LEN - 4;
    return [
      {
        id: "drop",
        lane: "Clock",
        label: "drop in",
        start: DROP_AT - PREROLL,
        length: 9,
        beats: { draw: 2, drawLen: 12, labels: 5, labelsLen: 8 },
      },
      {
        id: "seconds",
        lane: "Clock",
        label: "seconds",
        start: TICK_AT - PREROLL,
        length: redAt - TICK_AT,
        follows: "drop",
        beats: { tick },
      },
      {
        id: "tenths",
        lane: "Clock",
        label: "tenths",
        start: redAt - PREROLL,
        length: buzzAt - redAt,
        follows: "seconds",
        beats: { tenth: TENTH, kick: 8 },
      },
      {
        id: "buzzer",
        lane: "Clock",
        label: "buzzer",
        start: buzzAt - PREROLL,
        length: hold,
        follows: "tenths",
        beats: { flash: 9, kick: 10, ground: 6 },
      },
      {
        id: "shrink",
        lane: "Clock",
        label: "shrink",
        start: shrinkAt - PREROLL,
        length: SHRINK_LEN,
        follows: "buzzer",
      },
      {
        id: "title",
        lane: "Title",
        label: "title",
        start: titleAt - PREROLL,
        length: 7,
        follows: "shrink",
        beats: { kickAt: 3, kick: 8 },
      },
      {
        id: "subtitle",
        lane: "Title",
        label: "subtitle",
        start: titleAt + 4 - PREROLL,
        length: 9,
        follows: "title",
      },
    ];
  },
);
